def blockcount(g, rh, cws):
    out=[[0]*len(cws) for _ in range(len(rh))]
    rb=[sum(rh[:i]) for i in range(len(rh)+1)]
    cb=[sum(cws[:i]) for i in range(len(cws)+1)]
    for r in range(len(g)):
        for c in range(len(g[0])):
            if g[r][c]:
                ri=max(i for i in range(len(rh)) if rb[i]<=r)
                ci=max(i for i in range(len(cws)) if cb[i]<=c)
                out[ri][ci]+=1
    return out
